        rs=[p[0] for p in S]; cs=[p[1] for p in S]
        rmin,rmax,cmin,cmax=min(rs),max(rs),min(cs),max(cs)
        # closed rectangle ring: every cell degree-2 orthogonal, full perimeter
        if k<4 or not all(sum(1 for di,dj in ((1,0),(-1,0),(0,1),(0,-1)) if (a+di,b+dj) in S)==2 for a,b in S) or \
           len({(r,c) for r in range(rmin,rmax+1) for c in range(cmin,cmax+1) if (r,c) in S})!=2*(rmax-rmin+1)+2*(cmax-cmin+1)-4: continue
        rings.append((S,rmin,rmax,cmin,cmax))
    # exterior reachability from grid border over 0s (rings block)
    reach=[[False]*w for _ in range(h)]; q=deque()
    for x in range(h):
        for y in (0,w-1):
            if I[x][y]==0 and not reach[x][y]: reach[x][y]=True;q.append((x,y))
    for y in range(w):
        for x in (0,h-1):
            if I[x][y]==0 and not reach[x][y]: reach[x][y]=True;q.append((x,y))
    while q:
        a,b=q.popleft()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            n=(a+di,b+dj)
            if 0<=n[0]<h and 0<=n[1]<w and I[n[0]][n[1]]==0 and not reach[n[0]][n[1]]:
                reach[n[0]][n[1]]=True;q.append(n)
    for S,rmin,rmax,cmin,cmax in rings:
        # interior = enclosed zeros: inside bbox, not reached
        for i in range(rmin,rmax+1):
            for j in range(cmin,cmax+1):
                if I[i][j]==0 and not reach[i][j]:
                    adj=any((i+di,j+dj) in S for di in (-1,0,1) for dj in (-1,0,1) if (di,dj)!=(0,0))
                    if adj: O[i][j]=3
        for a,b in S:
            for di in (-1,0,1):
                for dj in (-1,0,1):
                    x,y=a+di,b+dj
                    if 0<=x<h and 0<=y<w and I[x][y]==0: O[x][y]=2
    return O

